def assert_response(responseBody, globalParam, statusCode, headers):
    if statusCode == 429:
        raise Blocked('首次请求已受限；共享身份初态不满足，待自然恢复后独立重试')
    if statusCode != 200 or not isinstance(responseBody, dict) or responseBody.get('code') != 0:
        return False
    data = responseBody.get('data')
    return isinstance(data, dict) and (isinstance(data.get('next_send_after'), int) and (not isinstance(data.get('next_send_after'), bool))) and (0 < data['next_send_after'] <= 2592000) and (isinstance(data.get('expires_in'), int) and (not isinstance(data.get('expires_in'), bool))) and (data['expires_in'] > 0)

def assert_response(responseBody, globalParam, statusCode, headers):
    if statusCode != 429 or not isinstance(responseBody, dict) or responseBody.get('code') != 42901:
        return False
    data = responseBody.get('data')
    if isinstance(data, dict) and (isinstance(data.get('next_send_after'), int) and (not isinstance(data.get('next_send_after'), bool))) and (data['next_send_after'] > 0):
        return True
    retry = headers.get('retry-after', [])
    return bool(retry) and retry[0].isdigit() and (int(retry[0]) > 0)

